// Package build waste (aidream billing.ci_package_build): one row per package built by one CI job.
// Rules + reasons live in aidream/services/billing/build_waste_rules.py; this file only reads and groups.
import type { SupabaseClient } from "@supabase/supabase-js";
import { supabase } from "@/utils/supabase/client";

// billing.ci_package_build is newer than the generated database types (regenerated by the type sync);
// until then the table is read through the untyped client shape.
const builds = () => (supabase.schema("billing") as unknown as SupabaseClient).from("ci_package_build");

export interface BuildRow {
  ecosystem: "npm" | "pypi" | "docker";
  package: string;
  outcome: string;
  no_op: boolean;
  reason: string | null;
  billed_minutes: number;
  cost_usd: number;
  requested_by: string | null;
  trigger: string;
  built_at: string;
}

/** One build as the drill reads it: the flat set every rollup is a sum of. */
export interface BuildCell {
  id: string;
  package: string;
  ecosystem: string;
  trigger: string;
  dispatcher: string;
  reason: string;
  outcome: string;
  builtAt: string;
  minutes: number;
  noopMinutes: number;
  noopUsd: number;
  /** 100 for a no-op build, 0 otherwise: its average over a group is the no-op %. */
  noopPct: number;
}

export function toCells(rows: BuildRow[]): BuildCell[] {
  return rows.map((r, i) => ({
    id: `${i}`,
    package: r.package,
    ecosystem: r.ecosystem,
    trigger: r.trigger,
    dispatcher: r.requested_by ?? "",
    reason: r.reason ?? "",
    outcome: r.outcome,
    builtAt: r.built_at,
    minutes: Number(r.billed_minutes) || 0,
    noopMinutes: r.no_op ? Number(r.billed_minutes) || 0 : 0,
    noopUsd: r.no_op ? Number(r.cost_usd) || 0 : 0,
    noopPct: r.no_op ? 100 : 0,
  }));
}

export interface PackageWaste {
  id: string;
  ecosystem: string;
  package: string;
  builds: number;
  noop: number;
  noopPct: number;
  minutes: number;
  noopMinutes: number;
  noopUsd: number;
  topReason: string | null;
}

const PAGE = 1000;

export async function fetchBuilds(days: number): Promise<BuildRow[]> {
  const since = new Date(Date.now() - days * 86_400_000).toISOString();
  const out: BuildRow[] = [];
  for (let from = 0; ; from += PAGE) {
    const { data, error } = await builds()
      .select("ecosystem, package, outcome, no_op, reason, billed_minutes, cost_usd, requested_by, trigger, built_at")
      .gte("built_at", since)
      .is("deleted_at", null)
      .order("built_at", { ascending: false })
      .range(from, from + PAGE - 1);
    if (error) throw new Error(error.message);
    out.push(...((data ?? []) as unknown as BuildRow[]));
    if (!data || data.length < PAGE) return out;
  }
}

export function byPackage(rows: BuildRow[]): PackageWaste[] {
  const map = new Map<string, PackageWaste & { reasons: Map<string, number> }>();
  for (const r of rows) {
    const id = `${r.ecosystem}:${r.package}`;
    const p = map.get(id) ?? { id, ecosystem: r.ecosystem, package: r.package, builds: 0, noop: 0, noopPct: 0, minutes: 0, noopMinutes: 0, noopUsd: 0, topReason: null, reasons: new Map() };
    p.builds += 1;
    p.minutes += r.billed_minutes;
    if (r.no_op) {
      p.noop += 1;
      p.noopMinutes += r.billed_minutes;
      p.noopUsd += Number(r.cost_usd);
      if (r.reason) p.reasons.set(r.reason, (p.reasons.get(r.reason) ?? 0) + 1);
    }
    map.set(id, p);
  }
  return [...map.values()]
    .map(({ reasons, ...p }) => ({
      ...p,
      noopPct: p.builds ? Math.round((1000 * p.noop) / p.builds) / 10 : 0,
      topReason: [...reasons.entries()].sort((a, b) => b[1] - a[1])[0]?.[0] ?? null,
    }))
    .sort((a, b) => b.noopMinutes - a.noopMinutes);
}
